def norm(s: str) -> str:
    return re.sub(r"[\s\-_·.,()\[\]/]", "", str(s or "")).lower()


# ── 노트 읽기 ──────────────────────────────────────────────────────────────

def _is_text_line(line: str) -> bool:
    s = EMBED.sub("", line).strip(" -\t")
    return bool(s) and not PRODUCT_URL.search(line) and not STORE_LINE.match(line) and not CONNECT.search(line)


def _strip_label(s: str) -> str:
    return re.sub(r"^[^:：|]{1,8}[:：]\s*$", "", s.strip())  # '리뷰1:' '태블릿:' 같은 이름표만 남은 경우


def targets(only: str | None = None) -> list[dict]:
    """쇼핑커넥트 링크 하나 = 상품 하나. 그 링크부터 다음 링크 전까지에서 상품명·판매처·상품 주소를 찾는다."""
    out = []
    for f in sorted(glob.glob(os.path.join(KW_DIR, "*.md"))):
        kw = os.path.splitext(os.path.basename(f))[0]
        if only and norm(kw) != norm(only):
            continue
        m = SECTION.search(open(f, encoding="utf-8").read())
        if not m:
            continue
        lines = m.group(1).splitlines()
        anchors = [i for i, l in enumerate(lines) if CONNECT.search(l)]
        for n, i in enumerate(anchors):
            block = lines[i + 1:(anchors[n + 1] if n + 1 < len(anchors) else len(lines))]
            line = EMBED.sub("", lines[i])
            connect = CONNECT.search(line).group(0)
            fields = [x.strip() for x in line.split("|")]
            link_at = next(k for k, x in enumerate(fields) if CONNECT.search(x))
            name = _strip_label(" ".join(CONNECT.sub("", x) for x in fields[:link_at + 1]).strip(" -\t"))
            store = fields[link_at + 1] if link_at + 1 < len(fields) else ""
            if not name:
                name = next((EMBED.sub("", l).strip(" -\t") for l in block if _is_text_line(l)), "")
            if not store:
                store = next((STORE_LINE.match(l).group(1) for l in block if STORE_LINE.match(l)), "")
            pm = next((PRODUCT_URL.search(l) for l in block + [lines[i]] if PRODUCT_URL.search(l)), None)
            out.append({
                "keyword": kw, "file": f, "name": name, "store": store.strip(), "connect": connect,
                "url": clean_url(pm.group(1).rstrip(")>")) if pm else "",
            })
    return out




def clean_url(url: str) -> str:
    """상품 주소에서 쿼리를 뗀다. 쇼핑커넥트를 거쳐 온 주소에는 `?NaPm=…ci=affiliate|tr=aff…` 제휴 추적값이 붙어 있어
    그대로 열면 제휴 유입으로 다시 잡힐 수 있다 — 스토어 상품 페이지 주소만 연다(10-03)."""
    m = STORE_PRODUCT.match(url)
    return m.group(0) if m else url.split("?")[0].split("#")[0]






